const positions = $input.first().json;
if (!Array.isArray(positions) || positions.length === 0) {
  return [{ json: { actions: [], alerts: [], unpriceable: [], positionCount: 0 } }];
}

const SUPABASE = 'https://fdabygmromuqtysitodp.supabase.co';
const headers = {
  'apikey': $env.SUPABASE_SERVICE_ROLE_KEY,
  'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY
};

// simulation_id -> conditionId. trading_positions stores no Polymarket
// identifier of its own (market_id is a uuid FK to trading_markets and stays
// NULL), so the simulation row is the only route back to a priceable market.
async function conditionIdFor(pos) {
  if (!pos.simulation_id) return null;
  const url = SUPABASE + '/rest/v1/trading_simulations?id=eq.'
    + encodeURIComponent(pos.simulation_id) + '&select=raw_output';
  const resp = await fetch(url, { headers });
  if (!resp.ok) {
    throw new Error('simulation lookup failed ' + resp.status + ': ' + (await resp.text()));
  }
  const rows = await resp.json();
  const raw = rows && rows[0] && rows[0].raw_output;
  return (raw && (raw.polymarket_condition_id || raw.condition_id)) || null;
}

async function priceFor(conditionId, direction) {
  const url = 'https://gamma-api.polymarket.com/markets?condition_ids='
    + encodeURIComponent(conditionId);
  const resp = await fetch(url);
  if (!resp.ok) return null;
  const markets = await resp.json();
  const market = Array.isArray(markets) ? markets[0] : markets;
  if (!market) return null;
  const prices = typeof market.outcomePrices === 'string'
    ? JSON.parse(market.outcomePrices)
    : market.outcomePrices;
  if (!prices) return null;
  if (direction === 'YES' && prices[0] != null) return parseFloat(prices[0]);
  if (direction === 'NO' && prices[1] != null) return parseFloat(prices[1]);
  return null;
}

const actions = [];
const alerts = [];
const unpriceable = [];

for (const pos of positions) {
  // One bad position must not abort the whole sweep and leave healthy
  // positions unmonitored, so each is evaluated inside its own try.
  let conditionId = null;
  let currentPrice = null;
  try {
    conditionId = await conditionIdFor(pos);
    if (conditionId) currentPrice = await priceFor(conditionId, pos.direction);
  } catch (e) {
    unpriceable.push({ id: pos.id, reason: String((e && e.message) || e) });
    continue;
  }

  if (currentPrice == null) {
    // No price means no exit decision. Do NOT fall back to entry_price —
    // that silently guarantees the position never exits.
    unpriceable.push({
      id: pos.id,
      reason: conditionId ? 'no_price_available' : 'no_condition_id'
    });
    continue;
  }

  // entry_price is NULL when the fill price could not be determined. Rules
  // that depend on it are SKIPPED rather than evaluated against 0, which
  // would silently disable the stop loss.
  const entryPrice = pos.entry_price == null ? null : Number(pos.entry_price);
  const shares = pos.shares != null ? Number(pos.shares) : null;
  const usdc = pos.usdc_amount != null ? Number(pos.usdc_amount) : null;
  const base = { id: pos.id, conditionId, currentPrice, entryPrice, shares, usdc };

  if (currentPrice > 0.85) {
    // Independent of entry price, so it still fires when entry_price is NULL.
    actions.push({ ...base, action: 'exit', reason: 'take_profit' });
  } else if (entryPrice != null && currentPrice < 0.08 && entryPrice > 0.20) {
    actions.push({ ...base, action: 'exit', reason: 'stop_loss' });
  } else if (entryPrice != null && currentPrice < 0.30 && entryPrice > 0.50) {
    alerts.push({ ...base, question: pos.id });
  } else if (entryPrice == null) {
    unpriceable.push({ id: pos.id, reason: 'no_entry_price_stop_loss_disabled' });
  }
}

return [{ json: { actions, alerts, unpriceable, positionCount: positions.length } }];

const data = $input.first().json;

const SUPABASE = 'https://fdabygmromuqtysitodp.supabase.co';
const headers = {
  'apikey': $env.SUPABASE_SERVICE_ROLE_KEY,
  'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY,
  'Content-Type': 'application/json'
};

async function patchPosition(id, body) {
  const resp = await fetch(SUPABASE + '/rest/v1/trading_positions?id=eq.'
    + encodeURIComponent(id), {
    method: 'PATCH',
    headers,
    body: JSON.stringify(body)
  });
  // Without this the node reports success on a 400 and the position stays
  // open in the DB while the operator is told it closed.
  if (!resp.ok) {
    const text = await resp.text();
    throw new Error('PATCH failed ' + resp.status + ': ' + text);
  }
  return resp;
}

const closed = [];

for (const a of data.actions.filter(a => a.action === 'exit')) {
  // exit_usdc = shares * exit price; pnl = proceeds - cost. Both need shares
  // and usdc_amount, which the Python executor writes at entry. Null when
  // absent rather than guessed — a wrong pnl is worse than a missing one, and
  // it would feed the executor's daily-loss gate.
  const exitUsdc = (a.shares != null && a.currentPrice != null)
    ? Number((a.shares * a.currentPrice).toFixed(6))
    : null;
  const pnl = (exitUsdc != null && a.usdc != null)
    ? Number((exitUsdc - a.usdc).toFixed(6))
    : null;

  await patchPosition(a.id, {
    status: 'closed',
    exit_reason: a.reason,
    exit_price: a.currentPrice,
    exit_usdc: exitUsdc,
    pnl: pnl,
    closed_at: new Date().toISOString()
  });
  closed.push({ id: a.id, reason: a.reason, exit_price: a.currentPrice,
                exit_usdc: exitUsdc, pnl });
}

return [{ json: { ...data, closed, updated: true } }];

